text:
Here's a water tracker with a goal of 8 glasses. Tap a glass or use + and − to log your day. It resets each morning.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; background: #eef7fb; color: #12394d; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  #count { font-size: 48px; font-weight: 700; margin: 12px 0 4px; }
  #msg { height: 22px; margin-bottom: 16px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; max-width: 360px; margin: 0 auto 20px; }
  .g { width: 60px; height: 76px; border: 3px solid #4aa3c7; border-radius: 4px 4px 14px 14px; background: #fff; cursor: pointer; padding: 0; }
  .g.full { background: linear-gradient(#7cc8e8, #3a97c0); }
  .bar { height: 12px; background: #d3e8f1; border-radius: 6px; max-width: 360px; margin: 0 auto 20px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #3a97c0; transition: width .3s; }
  button.b { font-size: 18px; padding: 8px 18px; margin: 0 4px; border: 0; border-radius: 8px; background: #3a97c0; color: #fff; cursor: pointer; }
  button.r { background: #9bb4c0; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div class="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button class="b" id="minus">−</button>
  <button class="b" id="plus">+</button>
  <button class="b r" id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var n = 0;
  try {
    var saved = JSON.parse(localStorage.getItem("water") || "{}");
    if (saved.d === today) n = saved.n;
  } catch (e) {}

  function save() {
    try { localStorage.setItem("water", JSON.stringify({ d: today, n: n })); } catch (e) {}
  }

  function draw() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Nicely done! 💧" : (GOAL - n) + " more to go";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 1; i <= GOAL; i++) {
      var g = document.createElement("button");
      g.className = "g" + (i <= n ? " full" : "");
      g.setAttribute("aria-label", "Glass " + i);
      (function (k) {
        g.onclick = function () { n = (n === k) ? k - 1 : k; save(); draw(); };
      })(i);
      box.appendChild(g);
    }
  }

  document.getElementById("plus").onclick = function () { n++; save(); draw(); };
  document.getElementById("minus").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

